// =============================================================================
// build-llm-prompt.js  (v2, TFI corregido)
// -----------------------------------------------------------------------------
// Pegar en un nodo "Code" (modo: "Run Once for Each Item") entre Insert Order
// y Call OpenAI. El estado 'error' se filtra antes de este nodo mediante un IF
// upstream — no debería llegar acá.
//
// Cambios vs v1 (ver prompts/v2.md):
//   - El contexto que va al LLM NO incluye pseudonym, ni nombre, correo o
//     teléfono. Ningún identificador de cliente cruza el límite del modelo.
//   - Se omiten claves con valor null/undefined/'' antes de serializar, para
//     que el modelo no pueda referirse a datos ausentes.
//   - Se instruye al modelo a iniciar el mensaje con el token literal
//     {{saludo}} (rehidratado por el validador posterior).
//   - Output esperado: { mensaje, atributos_usados }.
//   - Salvaguarda: throw si detecta que alguna PII se coló al contexto.
// =============================================================================

const PROMPT_VERSION = 'v2';

const HYPERPARAMS = {
    temperature: 0.4,
    top_p: 0.9,
    max_tokens: 220,
    response_format: { type: 'json_object' },
    seed: 42,
};

const SYSTEM_MESSAGE = `Sos un asistente de comunicación post-venta para una PyME argentina que vende
neumáticos por canales de comercio electrónico. Tu única tarea es redactar
mensajes cortos y cordiales para enviar al comprador tras un cambio de estado
de su pedido.

REGLAS ESTRICTAS

1. El mensaje DEBE comenzar exactamente con el token literal:
       {{saludo}}
   No lo reemplaces, no lo traduzcas, no antepongas ninguna palabra ni signo.
   Un proceso posterior sustituye el token por el saludo real con el nombre
   del cliente recuperado de la base local.

2. Solo podés usar la información que aparece en el objeto JSON del user
   message. Si un campo no está presente en el objeto, no lo inventes ni
   asumas su valor: omitilo del mensaje.

3. Nunca menciones nombre, correo, teléfono ni identificadores del cliente:
   el contexto que recibís NO los incluye. Si los inventaras, el validador
   posterior lo detecta y descarta tu respuesta.

4. Nunca menciones "OpenAI", "IA", "modelo de lenguaje", "asistente virtual"
   ni referencias a la implementación.

5. Tono: argentino neutro, cordial pero no informal. Usá "vos", no "tú" ni
   "usted". Sin emojis salvo que el contexto los pida.

6. Longitud: máximo 4 oraciones, ideal 2-3. No prometas tiempos de entrega,
   descuentos ni acciones que el contexto no confirme.

MAPEO ESTADO → CONTENIDO

Según order_status el mensaje debe orientarse así:

- created:          Confirmá recepción del pedido. Sin promesa de tiempos.
- pending_payment:  Indicá que aguardamos la confirmación del pago, sin urgencia.
- paid:             Confirmá el pago y avisá que el pedido pasa a preparación.
- preparing:        Avisá que el pedido se está armando.
- shipped:          Comunicá que el pedido fue despachado. No inventes número
                    de seguimiento si el contexto no lo trae.
- delivered:        Confirmá la entrega y agradecé la compra.
- cancelled:        Comunicá la cancelación del pedido de forma clara. No
                    minimices, no digas "estamos revisando".
- refunded:         Confirmá el reembolso.

Nota: si recibís este mensaje es porque el estado NO es 'error'. El estado
'error' se filtra antes y no llega al modelo.

OUTPUT

Devolvé EXCLUSIVAMENTE un objeto JSON válido con esta estructura:

{
  "mensaje": "{{saludo}}, ...",
  "atributos_usados": ["order_status", "primary_product_name", ...]
}

atributos_usados es la lista de claves del contexto que efectivamente citaste
en el mensaje. Sé preciso: sólo las que aparecen. Si mencionás "tu pedido"
sin referirte al producto, no incluyas primary_product_name.`;

// --- Helpers -----------------------------------------------------------------

// Toma el ítem de mayor monto como representativo (para mensajes de 1 producto).
function getPrimaryProductName(items) {
    if (!items || items.length === 0) return null;
    const sorted = [...items].sort(
        (a, b) => (Number(b.unit_price) * Number(b.quantity)) -
                  (Number(a.unit_price) * Number(a.quantity))
    );
    return sorted[0].product_name;
}

// Elimina del objeto las claves con valor null, undefined o string vacío.
// El modelo no debe ver "campo: null" — omitirlos previene alucinaciones.
function stripEmpty(obj) {
    const out = {};
    for (const [k, v] of Object.entries(obj)) {
        if (v === null || v === undefined) continue;
        if (typeof v === 'string' && v.trim() === '') continue;
        out[k] = v;
    }
    return out;
}

// Construye el contexto que va al LLM. NUNCA incluir PII.
function buildContext(input) {
    const raw = {
        order_status:         input.order.status,
        channel:              input.order.channel,
        items_count:          (input.items || []).length,
        primary_product_name: getPrimaryProductName(input.items),
        total_amount:         input.order.total_amount,
        currency:             input.order.currency,
        source_created_at:    input.order.source_created_at,
    };
    const ctx = stripEmpty(raw);

    // Red de seguridad: nunca debe aparecer PII en el contexto que va al LLM.
    // Si algún campo prohibido se coló (bug de un cambio futuro), abortamos
    // antes de invocar al modelo y consumir tokens.
    const pii_keys = [
        'full_name', 'email', 'phone', 'doc_number', 'address',
        'first_name', 'last_name', 'pseudonym', 'external_id',
    ];
    const ctx_str = JSON.stringify(ctx).toLowerCase();
    for (const key of pii_keys) {
        if (ctx_str.includes(`"${key}"`)) {
            throw new Error(`PII leak detected: campo '${key}' no debe llegar al LLM`);
        }
    }
    return ctx;
}

function buildUserMessage(ctx) {
    return `Contexto del pedido:
${JSON.stringify(ctx, null, 2)}

Generá el mensaje según las reglas del system.`;
}

// --- Main --------------------------------------------------------------------
const input = $('Route to canonical').item.json;

if (!input.customer || !input.order) {
    throw new Error('Input inválido: faltan customer u order. Verificar el normalizador.');
}
if (input.order.status === 'error') {
    // Guardián secundario: si por algún motivo llegara con status=error, no
    // gastamos tokens. La ruta primaria de filtrado está en el IF upstream.
    throw new Error("Estado 'error' no debe llegar a Build LLM prompt.");
}

const t_build_start = Date.now();
const context = buildContext(input);
const userMessage = buildUserMessage(context);

return {
    json: {
        order_id:       $('Insert Order').item.json.order_id,
        customer_id:    $('Upsert customer').item.json.customer_id,
        prompt_version: PROMPT_VERSION,

        messages: [
            { role: 'system', content: SYSTEM_MESSAGE },
            { role: 'user',   content: userMessage },
        ],
        model: 'gpt-4o-mini',
        ...HYPERPARAMS,

        prompt_build_ms:      Date.now() - t_build_start,
        sent_context:         context,
        llm_call_started_at:  new Date().toISOString(),
    },
};

// =============================================================================
// parse-llm-response.js  (v2, TFI corregido)
// -----------------------------------------------------------------------------
// Pegar en un nodo "Code" (modo: "Run Once for Each Item") DESPUÉS del nodo
// OpenAI/Anthropic.
//
// Función:
//   - Extrae el texto generado y la metadata de uso (tokens, latencia)
//   - Valida que sea JSON parseable con la shape v2: { mensaje, atributos_usados }
//   - Verifica que el mensaje comience con el token {{saludo}} (rehidratado
//     por el validador determinístico posterior, spec de B3)
//   - Calcula cost_usd usando el pricing del proveedor
//   - Devuelve un item con message_text + atributos_usados listo para el
//     validador posterior; o con use_fallback=true para redirigir a la
//     plantilla determinística.
//
// Pricing por 1M tokens (actualizar cuando cambien las tarifas).
// Fuente: https://openai.com/pricing
// =============================================================================

const PRICING = {
    openai: {
        // Vigente al 2026-09-01
        'gpt-4o-mini':  { input: 0.150, output: 0.600 },
        'gpt-4o':       { input: 2.500, output: 10.000 },
    },
    anthropic: {
        'claude-haiku-4-5':   { input: 1.000, output: 5.000 },
        'claude-haiku-3-5':   { input: 0.800, output: 4.000 },
    },
};

const MAX_MESSAGE_LENGTH = 600;
const MIN_MESSAGE_LENGTH = 20;
const SALUDO_TOKEN = '{{saludo}}';

// --- Helpers -----------------------------------------------------------------
function calculateCostUSD(provider, model, promptTokens, completionTokens) {
    const tier = PRICING[provider] && PRICING[provider][model];
    if (!tier) return null;
    const inputCost  = (promptTokens     || 0) * tier.input  / 1_000_000;
    const outputCost = (completionTokens || 0) * tier.output / 1_000_000;
    return Number((inputCost + outputCost).toFixed(6));
}

function extractTextAndUsage(llmRaw) {
    // Camino 0: primitivo
    if (typeof llmRaw === 'string') return { text: llmRaw, usage: {} };
    if (!llmRaw || typeof llmRaw !== 'object') return { text: '', usage: {} };

    // Camino 1: OpenAI Chat Completions crudo → choices[0].message.content
    if (Array.isArray(llmRaw.choices) && llmRaw.choices[0]) {
        const ch = llmRaw.choices[0];
        const text = (ch.message && ch.message.content) || ch.text || '';
        return { text, usage: llmRaw.usage || {} };
    }

    // Camino 2: n8n LangChain OpenAI "Message a Model" op → { message: { content: [{type:"output_text", text}] } }
    if (llmRaw.message && llmRaw.message.content) {
        const mc = llmRaw.message.content;
        if (Array.isArray(mc) && mc[0]) {
            const b = mc[0];
            return { text: b.text || b.content || (typeof b === 'string' ? b : ''), usage: llmRaw.usage || llmRaw.tokenUsage || {} };
        }
        if (typeof mc === 'string') return { text: mc, usage: llmRaw.usage || {} };
    }

    // Camino 3: OpenAI Responses API / algunas versiones del nodo → { content: [{type:"output_text", text}] } al top
    if (Array.isArray(llmRaw.content) && llmRaw.content[0]) {
        const b = llmRaw.content[0];
        const text = b.text || b.content || (typeof b === 'string' ? b : '');
        const usage = llmRaw.usage ? {
            prompt_tokens:     llmRaw.usage.input_tokens     || llmRaw.usage.prompt_tokens,
            completion_tokens: llmRaw.usage.output_tokens    || llmRaw.usage.completion_tokens,
        } : {};
        return { text, usage };
    }

    // Camino 4: strings simples en top-level
    if (typeof llmRaw.content === 'string') return { text: llmRaw.content, usage: llmRaw.usage || {} };
    if (typeof llmRaw.text === 'string')    return { text: llmRaw.text,    usage: llmRaw.usage || {} };
    if (typeof llmRaw.output === 'string')  return { text: llmRaw.output,  usage: llmRaw.usage || {} };

    // Camino 5 (defensa en profundidad): walker recursivo — busca la primera propiedad
    // 'text' que sea string no vacío. Cubre wrappers futuros del nodo sin re-tocar código.
    function walk(node, depth) {
        if (!node || depth > 6) return null;
        if (typeof node === 'object' && !Array.isArray(node)) {
            if (typeof node.text === 'string' && node.text.trim() !== '') return node.text;
            for (const v of Object.values(node)) {
                const r = walk(v, depth + 1);
                if (r) return r;
            }
        } else if (Array.isArray(node)) {
            for (const v of node) {
                const r = walk(v, depth + 1);
                if (r) return r;
            }
        }
        return null;
    }
    const walked = walk(llmRaw, 0);
    if (walked) return { text: walked, usage: llmRaw.usage || {} };

    return { text: '', usage: {} };
}

// Valida el shape v2: { mensaje: string, atributos_usados: string[] }
function parseAndValidate(text) {
    const out = { valid: false, parsed: null, errors: [] };

    if (!text || typeof text !== 'string') {
        out.errors.push('empty_response');
        return out;
    }

    let parsed;
    try {
        const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
        parsed = JSON.parse(cleaned);
    } catch (e) {
        out.errors.push(`invalid_json:${e.message}`);
        return out;
    }

    if (typeof parsed.mensaje !== 'string') {
        out.errors.push('missing_field:mensaje');
    } else {
        if (parsed.mensaje.length < MIN_MESSAGE_LENGTH) {
            out.errors.push(`message_too_short:${parsed.mensaje.length}`);
        }
        if (parsed.mensaje.length > MAX_MESSAGE_LENGTH) {
            out.errors.push(`message_too_long:${parsed.mensaje.length}`);
        }
        // El mensaje debe empezar con {{saludo}} (rehidratado por B3).
        // Aceptamos que haya venido con o sin espacio previo por robustez.
        if (!parsed.mensaje.trimStart().startsWith(SALUDO_TOKEN)) {
            out.errors.push('saludo_token_missing');
        }
    }

    if (!Array.isArray(parsed.atributos_usados)) {
        out.errors.push('missing_field:atributos_usados');
    } else {
        const invalid = parsed.atributos_usados.filter(a => typeof a !== 'string');
        if (invalid.length > 0) out.errors.push('atributos_usados_not_strings');
    }

    out.valid = out.errors.length === 0;
    out.parsed = parsed;
    return out;
}

// --- Main --------------------------------------------------------------------
const input = $json;
const t_parse_start = Date.now();

// Identidad y contexto de la llamada — leídos desde Build LLM prompt para no
// depender del shape del proveedor. La respuesta de OpenAI devuelve el nombre
// completo con versión (p. ej. 'gpt-4o-mini-2024-07-18'), que no matchea la
// clave 'gpt-4o-mini' de la tabla PRICING y hacía que cost_usd quedara nulo.
const bp = $('Build LLM prompt').item.json;
const order_id       = bp.order_id;
const customer_id    = bp.customer_id;
const prompt_version = bp.prompt_version || 'v2';
const provider       = 'openai';
const model          = bp.model || 'gpt-4o-mini';
const startedAt      = bp.llm_call_started_at;

const llmRaw = input.response || input.data || input.llm || input;
const { text, usage } = extractTextAndUsage(llmRaw);
const validation = parseAndValidate(text);

const promptTokens     = usage.prompt_tokens     || usage.input_tokens     || null;
const completionTokens = usage.completion_tokens || usage.output_tokens    || null;
const costUSD          = calculateCostUSD(provider, model, promptTokens, completionTokens);

const latencyMs = startedAt
    ? (Date.now() - new Date(startedAt).getTime())
    : null;

if (validation.valid) {
    return {
        json: {
            order_id,
            customer_id,
            use_fallback: false,

            provider,
            model,
            prompt_version,

prompt_tokens: promptTokens,
            completion_tokens: completionTokens,
            usage: {
                prompt_tokens: promptTokens,
                completion_tokens: completionTokens,
            },
            cost_usd: costUSD,
            latency_ms: latencyMs,

            // v2: mensaje con {{saludo}} sin rehidratar; atributos declarados.
            message_text: validation.parsed.mensaje,
            atributos_usados: validation.parsed.atributos_usados,
            is_fallback: false,
            message_status: 'generated',
            error_message: null,

            audit_event: {
                event_type: 'llm_call_ok',
                severity: 'info',
                component: 'llm',
                message: `LLM ${provider}/${model} respondió OK`,
                payload: {
                    prompt_version,
                    tokens_prompt: promptTokens,
                    tokens_completion: completionTokens,
                    cost_usd: costUSD,
                    latency_ms: latencyMs,
                    atributos_usados: validation.parsed.atributos_usados,
                },
            },
        },
    };
}

return {
    json: {
        order_id,
        customer_id,
        use_fallback: true,
        fallback_reason: validation.errors.join(','),

        provider,
        model,
        prompt_version,
        cost_usd: costUSD,
        latency_ms: latencyMs,
        raw_response: text,
        validation_errors: validation.errors,

        order:    input.order    || null,
        customer: input.customer || null,
        items:    input.items    || null,

        audit_event: {
            event_type: 'llm_call_failed',
            severity: 'warning',
            component: 'llm',
            message: `LLM ${provider}/${model} devolvió respuesta inválida: ${validation.errors.join(', ')}`,
            payload: {
                prompt_version,
                errors: validation.errors,
                cost_usd: costUSD,
                latency_ms: latencyMs,
                raw_excerpt: text.slice(0, 200),
            },
        },
    },
};

// =============================================================================
// fallback-template.js
// -----------------------------------------------------------------------------
// Pegar en un nodo "Code" (modo: "Run Once for Each Item") en la rama de
// degradación funcional del workflow.
//
// Se invoca cuando:
//   - El LLM no responde dentro del timeout configurado
//   - La respuesta del LLM no parsea como JSON
//   - La respuesta no cumple la shape esperada (message/tone/confidence)
//   - El confidence devuelto es muy bajo (< 0.3)
//
// Produce un mensaje basado en plantilla estática por estado, garantizando
// que el cliente reciba algo aunque el componente generativo no funcione.
// Cap 5.8 del documento — degradación funcional controlada.
// =============================================================================

const TEMPLATE_VERSION = 'template-v1';

// Plantillas por estado del modelo canónico (alineadas con CHECK constraint
// de tfi.orders.status). Texto: argentino neutro, mismo tono que el prompt v1.
const TEMPLATES = {
    created: {
        message: 'Recibimos tu compra. Te avisamos en cuanto se confirme el pago.',
        tone: 'informativo',
    },
    pending_payment: {
        message: 'Estamos esperando la confirmación del pago de tu compra. Si ya pagaste, no te preocupes — en algunos casos puede demorar unos minutos.',
        tone: 'informativo',
    },
    paid: {
        message: 'Recibimos el pago de tu compra. Estamos preparando tu pedido para el envío. Gracias por elegirnos.',
        tone: 'cordial',
    },
    preparing: {
        message: 'Tu pedido se está preparando. Te avisamos en cuanto lo despachemos.',
        tone: 'informativo',
    },
    shipped: {
        message: 'Tu pedido fue despachado. Vas a recibirlo en los próximos días según el método de envío que elegiste.',
        tone: 'informativo',
    },
    delivered: {
        message: 'Confirmamos la entrega de tu pedido. ¡Gracias por tu compra! Si necesitás algo, escribinos.',
        tone: 'celebratorio',
    },
    cancelled: {
        message: 'Tu pedido fue cancelado. Si fue un error o querés más información, contactanos así lo resolvemos.',
        tone: 'disculpa',
    },
    refunded: {
        message: 'Se procesó el reembolso de tu pedido. Puede demorar unos días en verse reflejado según tu medio de pago.',
        tone: 'disculpa',
    },
    error: {
        message: 'Estamos revisando algunos detalles de tu pedido. Te contactamos en cuanto tengamos novedades.',
        tone: 'informativo',
    },
};

// Plantilla absolutamente genérica si el estado tampoco existe en el map.
// No debería llegar acá si el normalizador funcionó (mapea estados desconocidos
// a 'error'), pero es defensa en profundidad.
const ULTIMATE_FALLBACK = {
    message: 'Recibimos tu compra. Te contactamos en cuanto haya novedades sobre tu pedido.',
    tone: 'informativo',
};

const input = $json;
// El status canónico vive en Route to canonical: Build LLM prompt no lo copia
// al reenviar hacia OpenAI, y Parse LLM Response reconstruye order sólo si
// existió en su input (que no es el caso). Leerlo directo evita la caída al
// ULTIMATE_FALLBACK cuando la plantilla específica del estado existía.
const status = $('Route to canonical').item.json.order.status;
const reason = input.fallback_reason || 'unknown';

const template = TEMPLATES[status] || ULTIMATE_FALLBACK;

return {
    json: {
        order_id: input.order_id,
        customer_id: input.customer_id,

        // Provider especial 'template' coherente con el CHECK constraint
        // de tfi.ai_notifications (provider='template' ↔ is_fallback=true)
        provider: 'template',
        model: null,
        prompt_version: null,

        // Sin tokens ni costo porque no fue llamada externa
        usage: { prompt_tokens: null, completion_tokens: null },
        cost_usd: 0,
        latency_ms: 0,

        // Output con la misma shape que devolvería el LLM, así el INSERT
        // posterior es uniforme y no requiere branching
        message_text: template.message,
        tone: template.tone,
        confidence: 1.0, // plantilla es 100% predecible

        // v2 (§3.3): las plantillas no explicitan qué atributos citan; se
        // reporta 'template' para diferenciar de una respuesta generativa
        // en las métricas de anclaje contextual sin inventar atributos.
        atributos_usados: ['template'],

        // v1.3 (§4.3.1): las plantillas son 100% determinísticas y no
        // pasan por el validador de reglas — no cuentan como pasada.
        validator_passes: 0,
        validator_failures: input.validator_failures || [],

        is_fallback: true,
        message_status: 'validated',

        // Telemetría: por qué se cayó al fallback
        fallback_reason: reason,
        template_version: TEMPLATE_VERSION,
        applied_template_status: status,

        // Para audit_log
        audit_event: {
            event_type: 'fallback_triggered',
            severity: 'warning',
            component: 'llm',
            message: `Degradación a plantilla por ${reason}`,
            payload: { fallback_reason: reason, status, template_version: TEMPLATE_VERSION },
        },
    },
};

const aiNotif = $('Insert ai_notification').first().json;
 const customerRow = $input.first().json;

 const notificationId = aiNotif.notification_id || null;
 const orderId        = aiNotif.order_id        || null;
 const messageText    = aiNotif.message_text    || '';
 const phone          = customerRow.phone       || null;
 const fullName       = customerRow.full_name   || null;

 return {
     json: {
         notification_id: notificationId,
         order_id:        orderId,
         message_text:    messageText,
         phone,
         full_name:       fullName,
     },
 };

// build-wa-payload.js
// Arma el payload para el HTTP Request a la Cloud API de Meta.
// Toma el teléfono del cliente (normalizado a E.164 argentino SIN "9").

function toE164Argentina(raw) {
    if (!raw) return null;
    let digits = raw.replace(/\D/g, '');
    // Ya viene con "9" del prefijo mobile → sacamos el "9" para matchear
    // el formato que registra Meta en su lista de recipients autorizados.
    if (digits.startsWith('549') && digits.length >= 12) return '+54' + digits.slice(3);
    if (digits.startsWith('54')  && digits.length >= 11) return '+' + digits;
    if (digits.startsWith('0')) digits = digits.slice(1);
    if (digits.length === 10) return '+54' + digits;
    if (digits.length === 8)  return '+5411' + digits;
    return null;
}

function buildGreeting(fullName) {
    if (!fullName) return '';
    const firstName = fullName.trim().split(/\s+/)[0];
    return 'Hola ' + firstName + '!\n';
}

const input = $json;
const customerRow = Array.isArray(input) ? input[0] : input;

const rawPhone       = customerRow.phone     || input.phone     || null;
const fullName       = customerRow.full_name || input.full_name || null;
const notificationId = input.notification_id || input.id        || null;
const messageText    = input.message_text    || input.message   || '';
const orderId        = input.order_id                           || null;

const phone = toE164Argentina(rawPhone);

if (!phone) {
    return {
        json: {
            no_phone: true,
            reason: rawPhone ? 'phone_not_normalizable:' + rawPhone : 'phone_missing',
            notification_id: notificationId,
            order_id: orderId,
        },
    };
}

const greeting     = buildGreeting(fullName);
const finalMessage = (greeting + messageText).trim();

const metaBody = {
    messaging_product: 'whatsapp',
    recipient_type:    'individual',
    to:                phone,
    type:              'text',
    text: { preview_url: false, body: finalMessage },
};

return {
    json: {
        no_phone:        false,
        notification_id: notificationId,
        order_id:        orderId,
        to_phone:        phone,
        meta_body:       metaBody,
        audit_event: {
            event_type: 'dispatch_attempted',
            severity:   'info',
            component:  'dispatcher',
            message:    'Intentando envío WhatsApp a ' + phone,
            payload:    { notification_id: notificationId, to: phone },
        },
    },
};

const input = $json;

 const notificationId = input.notification_id || null;
 const orderId        = input.order_id        || null;
 const toPhone        = input.to_phone        || null;

 const httpError = input.error || input.message || null;
 const httpStatus = input.statusCode || input.status || null;
 const isHttpError = !!httpError || (httpStatus && httpStatus >= 400);

 if (isHttpError) {
     const errorDetail = typeof httpError === 'object'
         ? JSON.stringify(httpError)
         : String(httpError || `HTTP ${httpStatus}`);

     return {
         json: {
             notification_id: notificationId,
             order_id:        orderId,
             message_status:  'failed',
             wa_message_id:   null,
             error_reason:    errorDetail,
             audit_event: {
                 event_type: 'dispatch_failed',
                 severity:   'error',
                 component:  'dispatcher',
                 message:    `Meta API rechazó el mensaje: ${errorDetail.slice(0, 200)}`,
                 payload:    { notification_id: notificationId, to: toPhone, error: errorDetail },
             },
         },
     };
 }

 const waMessageId = (input.messages && input.messages[0] && input.messages[0].id) || null;

 if (!waMessageId) {
     return {
         json: {
             notification_id: notificationId,
             order_id:        orderId,
             message_status:  'failed',
             wa_message_id:   null,
             error_reason:    'meta_response_missing_message_id',
             audit_event: {
                 event_type: 'dispatch_failed',
                 severity:   'warning',
                 component:  'dispatcher',
                 message:    'Meta respondió 200 pero sin messages[0].id',
                 payload:    { notification_id: notificationId, raw_response: input },
             },
         },
     };
 }

 return {
     json: {
         notification_id: notificationId,
         order_id:        orderId,
         message_status:  'sent',
         wa_message_id:   waMessageId,
         error_reason:    null,
         audit_event: {
             event_type: 'dispatch_ok',
             severity:   'info',
             component:  'dispatcher',
             message:    `Mensaje enviado por WhatsApp (wamid: ${waMessageId})`,
             payload:    { notification_id: notificationId, to: toPhone, wa_message_id: waMessageId
 },
         },
     },
 };

// Loop over input items and add a new field called 'myNewField' to the const crypto = require('crypto');

const CHANNEL = 'woocommerce';
const SECRET = (typeof $env !== 'undefined' && $env.WC_WEBHOOK_SECRET) || '';

// --- Helpers -----------------------------------------------------------------

// Intenta recuperar el body CRUDO (bytes exactos) para validar la firma.
// n8n con "Raw Body: ON" lo deja en item.binary.data (base64) o en rawBody.
function getRawBody(item, bodyObj) {
    if (item.json && typeof item.json.rawBody === 'string') return item.json.rawBody;
    if (item.binary && item.binary.data && item.binary.data.data) {
        try { return Buffer.from(item.binary.data.data, 'base64').toString('utf8'); }
        catch (e) { /* ignore */ }
    }
    // Best-effort: re-serializa el objeto. Puede no coincidir byte a byte.
    return { fallback: true, value: JSON.stringify(bodyObj) };
}

// Comparación en tiempo constante para evitar timing attacks.
function safeEqual(a, b) {
    const ba = Buffer.from(String(a));
    const bb = Buffer.from(String(b));
    if (ba.length !== bb.length) return false;
    try { return crypto.timingSafeEqual(ba, bb); }
    catch (e) { return false; }
}

function getHeader(headers, name) {
    if (!headers) return null;
    // n8n normaliza los headers a minúsculas, pero soportamos ambos por las dudas.
    return headers[name] || headers[name.toLowerCase()] || null;
}

// --- Main loop ---------------------------------------------------------------
const results = [];

for (const item of $input.all()) {
    const raw = item.json || {};
    const headers = raw.headers || {};
    // El Webhook node de n8n envuelve el payload en item.json.body.
    const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
    const errors = [];
    const appliedRules = [];

    // 1. Detectar el ping de activación (WooCommerce manda {"webhook_id": N})
    const isPing = body && body.webhook_id !== undefined
        && body.id === undefined && body.line_items === undefined;
    if (isPing) {
        results.push({
            json: {
                valid: false, errors: ['ping'], is_ping: true, signature_valid: null,
                order: null, channel: CHANNEL, applied_rules: ['info:webhook_ping'],
                received_at: new Date().toISOString(),
            },
        });
        continue;
    }

    // 2. Validar la firma HMAC-SHA256 (base64)
    let signatureValid = null;
    if (!SECRET) {
        appliedRules.push('warn:wc_secret_not_configured_signature_skipped');
    } else {
        const provided = getHeader(headers, 'x-wc-webhook-signature');
        if (!provided) {
            errors.push('missing_signature_header');
            signatureValid = false;
        } else {
            const rawBody = getRawBody(item, body);
            const rawValue = (rawBody && rawBody.fallback) ? rawBody.value : rawBody;
            if (rawBody && rawBody.fallback) {
                appliedRules.push('warn:raw_body_unavailable_used_stringify');
            }
            const expected = crypto.createHmac('sha256', SECRET)
                .update(rawValue, 'utf8').digest('base64');
            signatureValid = safeEqual(expected, provided);
            if (!signatureValid) errors.push('invalid_signature');
        }
    }

    // 3. Estructura mínima del pedido
    if (body.id === undefined || body.id === null) errors.push('missing_field:id');
    if (!Array.isArray(body.line_items)) errors.push('missing_field:line_items');
    if (!body.billing || typeof body.billing !== 'object') {
        appliedRules.push('warn:billing_missing');
    }

    results.push({
        json: {
            valid: errors.length === 0,
            errors,
            is_ping: false,
            signature_valid: signatureValid,
            order: body,
            channel: CHANNEL,
            applied_rules: appliedRules,
            received_at: new Date().toISOString(),
        },
    });
}

return results;;

// =============================================================================
// normalize-wc-order.js
// -----------------------------------------------------------------------------
// Pegar en un nodo "Code" de n8n (modo: "Run Once for All Items") ubicado
// inmediatamente después del Webhook trigger de WooCommerce.
//
// Diferencia respecto del flujo ML:
//   - WC manda el pedido COMPLETO en el webhook (no necesita enrich extra)
//   - El shape es muy distinto: billing/shipping objects, line_items array,
//     status en lowercase con prefijos como 'wc-' en algunos casos
//
// Esta función traduce ese shape al MODELO CANÓNICO compartido con ML:
//   { customer, order, items, meta }
//
// A partir de este punto, el resto del pipeline es idéntico al de ML
// (idempotency → persist → IA → WhatsApp), por eso converge en el mismo
// formato canónico.
// =============================================================================

const crypto = require('crypto');

const NORMALIZATION_VERSION = 'v1';
const CHANNEL = 'woocommerce';

// --- Mapeo de estados WC → modelo canónico ----------------------------------
// WC nativos: pending, processing, on-hold, completed, cancelled, refunded, failed
const STATUS_MAP = {
    'pending':     'pending_payment',
    'on-hold':     'pending_payment',
    'processing':  'paid',         // pago confirmado, en preparación
    'completed':   'delivered',    // WC marca completed cuando ya se envió/entregó
    'cancelled':   'cancelled',
    'refunded':    'refunded',
    'failed':      'error',
};

// --- Helpers (mismas funciones que el normalizador de ML para consistencia) -
function sha256(value) {
    if (value === null || value === undefined || value === '') return null;
    return crypto.createHash('sha256').update(String(value).toLowerCase().trim()).digest('hex');
}
function makePseudonym(channel, externalId) {
    const hash = crypto.createHash('sha256').update(`${channel}:${externalId}`).digest('hex').slice(0, 12);
    return `cust_${hash}`;
}

// --- Main loop --------------------------------------------------------------
const out = [];

for (const item of $input.all()) {
    const t0 = Date.now();
    // v1.3: entre Validate WC webhook y este nodo se insertaron Persist raw
    // event WC + ACK 200 WC, por lo que $input ya no trae el body del pedido.
    // Se lee el pedido directamente desde Validate WC webhook, que lo emite
    // como `.order` (ver validate-wc-webhook.js).
    const wc = $('Validate WC webhook').item.json.order || {};

    const appliedRules = [];
    const billing = wc.billing || {};
    const shipping = wc.shipping || {};

    // El nombre real puede estar en billing (típicamente) o en shipping
    const fullName = [billing.first_name, billing.last_name].filter(Boolean).join(' ').trim()
        || [shipping.first_name, shipping.last_name].filter(Boolean).join(' ').trim()
        || null;
    const phone = billing.phone || shipping.phone || null;
    const email = billing.email || null;

    // WC tiene dos identificadores posibles del cliente:
    //   - customer_id (numérico, si es usuario registrado; 0 para guest checkouts)
    //   - email (fallback estable cuando es guest)
    let externalCustomerId = wc.customer_id && wc.customer_id !== 0
        ? String(wc.customer_id)
        : (email || null);

    // D1 (v1.3): si ninguno de los dos está disponible, se genera un identificador
    // sustituto determinístico `synthetic:{channel}:{order.external_id}`. Es
    // reproducible (mismo pedido reingresado hace UPSERT sobre la misma fila) y
    // trazable (el prefijo permite filtrar y contar sustituciones). Preserva la
    // integridad referencial (customers.external_id NOT NULL) sin bloquear el
    // pedido, según §4.6 del TFI corregido.
    if (!externalCustomerId) {
        externalCustomerId = `synthetic:${CHANNEL}:${wc.id}`;
        appliedRules.push('warn:customer_id_missing_substituted');
    }

    const customer = {
        external_id: externalCustomerId,
        channel: CHANNEL,
        pseudonym: makePseudonym(CHANNEL, externalCustomerId),
        full_name: fullName,
        email,
        phone,
        email_hash: sha256(email),
        phone_hash: sha256(phone),
    };

    // Status: WC a veces prefija con 'wc-' (status interno). Lo limpiamos.
    const rawStatus = String(wc.status || '').replace(/^wc-/, '').toLowerCase();
    const status = STATUS_MAP[rawStatus] || 'error';
    if (status === 'error') appliedRules.push(`warn:unmapped_status:${rawStatus}`);

    const order = {
        external_id: String(wc.id),
        channel: CHANNEL,
        status,
        total_amount: Number(wc.total) || 0,
        currency: wc.currency || 'ARS',
        source_created_at: wc.date_created_gmt || wc.date_created || new Date().toISOString(),
        raw_payload: wc,
        normalization_version: NORMALIZATION_VERSION,
    };

    // Estado de envío: WC no tiene un campo shipping.status como ML. Lo derivamos
    // del estado del pedido.
    const deliveryStatus =
        status === 'cancelled' ? 'cancelled' :
        status === 'delivered' ? 'delivered' :
        status === 'paid'      ? 'preparing' :
                                 'pending';

    const items = (wc.line_items || []).map((li) => ({
        sku: li.sku || String(li.product_id) || null,
        product_name: li.name || '(sin título)',
        quantity: Number(li.quantity) || 1,
        // line_items.price es el unitario; total/subtotal son los del item completo
        unit_price: Number(li.price ?? li.subtotal) || 0,
        delivery_status: deliveryStatus,
        metadata: {
            wc_item_id: li.id ?? null,
            wc_product_id: li.product_id ?? null,
            wc_variation_id: li.variation_id ?? null,
            tax_total: li.total_tax ?? null,
        },
    }));
    if (items.length === 0) appliedRules.push('warn:no_items');

    // v1.3: raw_event_id y ack_at vienen del nodo Persist raw event WC
    // (§4.1.1 del TFI corregido). El ack_at se persiste en tfi.orders y la
    // ventana received_at→ack_at debe quedar por debajo de 500 ms.
    const rawEvt = $('Persist raw event WC').item.json;

    out.push({
        json: {
            customer,
            order,
            items,
            raw_event_id: rawEvt.raw_event_id,
            ack_at: rawEvt.ack_at,
            meta: {
                normalization_ms: Date.now() - t0,
                applied_rules: appliedRules,
                normalization_version: NORMALIZATION_VERSION,
                source_channel: CHANNEL,
            },
        },
    });
}

return out;

